122|export class ManagedFunctionRouteRegistry {
123|  /** L1 resolve cache: `${METHOD}:${path}` → match or null */
124|  private resolveCache = new Map<string, ManagedFunctionRouteMatch | null>();
125|
126|  private entries: ManagedFunctionRouteEntry[] = [];
127|
128|  private loaded = false;
129|
130|  private loading: Promise<void> | null = null;
131|
132|  isReservedApiPath(pathname: string): boolean {
133|    const normalized = normalizeRequestPath(pathname);
134|    return RESERVED_API_PREFIXES.some((prefix) => (
135|      normalized === prefix || normalized.startsWith(`${prefix}/`)
136|    ));
137|  }
138|
139|  async ensureLoaded(): Promise<void> {
140|    if (this.loaded) {
141|      return;
142|    }
143|    if (this.entries.length > 0) {
144|      this.scheduleReload();
145|      return;
146|    }
147|    if (this.loading) {
148|      await this.loading;
149|      return;
150|    }
151|
152|    this.loading = this.reload().finally(() => {
153|      this.loading = null;
154|    });
155|    await this.loading;
156|  }
157|
158|  private scheduleReload(): void {
159|    if (this.loading) {
160|      return;
161|    }
162|    this.loading = this.reload().finally(() => {
163|      this.loading = null;
164|    });
165|  }
166|
167|  async reload(): Promise<void> {
168|    const rows = await listManagedFunctionRouteRows();
169|    this.entries = rows
170|      .map((row) => {
171|        const record = toManagedFunctionRecord(row as unknown as Record<string, unknown>);
172|        const compiled = compileRoutePattern(record.path || '');
173|        const isDirectSql = record.engineType === 'DIRECT_SQL' || record.engine_type === 'DIRECT_SQL';
174|        const metadataRecord = record.metadataJson && typeof record.metadataJson === 'object'
175|          ? record.metadataJson as Record<string, unknown>
176|          : null;
177|        const isMultiMethod = isDirectSql || isBundledAutoCrudOrigin(metadataRecord);
178|        return {
179|          ...record,
180|          ...compiled,
181|          isDirectSql,
182|          isMultiMethod,
183|        };
184|      })
185|      .sort((left, right) => (right.path?.length || 0) - (left.path?.length || 0));
186|
187|    this.resolveCache.clear();
188|    this.loaded = true;
189|  }
190|
191|  invalidate(functionId?: string): void {
192|    this.loaded = false;
193|    this.resolveCache.clear();
194|    if (functionId) {
195|      this.entries = this.entries.filter((entry) => entry.id !== functionId);
196|    }
197|    this.scheduleReload();
198|  }
199|
200|  isPublicManagedRoute(httpMethod: string, requestPath: string): boolean {
201|    const match = this.resolve(httpMethod, requestPath);
202|    if (!match) {
203|      return false;
204|    }
205|    return isPublicFunctionAccessControl(resolveEntryAccessControl(match.function as ManagedFunctionRouteEntry));
206|  }
207|
208|  resolve(httpMethod: string, requestPath: string): ManagedFunctionRouteMatch | null {
209|    const normalizedMethod = httpMethod.toUpperCase();
210|    const normalizedPath = normalizeRequestPath(requestPath);
211|    const cacheKey = `${normalizedMethod}:${normalizedPath}`;
212|
213|    if (this.resolveCache.has(cacheKey)) {
214|      return this.resolveCache.get(cacheKey) ?? null;
215|    }
216|
217|    for (const entry of this.entries) {
218|      if (!entry.isMultiMethod && entry.method.toUpperCase() !== normalizedMethod) {
219|        continue;
220|      }
221|
222|      const match = normalizedPath.match(entry.pathRegex);
223|      if (!match) {
224|        continue;
225|      }
226|
227|      const params: Record<string, string> = {};
228|      entry.paramNames.forEach((name, index) => {
229|        const value = match[index + 1];
230|        if (value !== undefined) {
231|          params[name] = decodeURIComponent(value);
232|        }
233|      });
234|
235|      const resolved: ManagedFunctionRouteMatch = {
236|        function: entry,
237|        params,
238|      };
239|      this.resolveCache.set(cacheKey, resolved);
240|      return resolved;
241|    }
242|
243|    this.resolveCache.set(cacheKey, null);
244|    return null;
245|  }
246|}
247|
248|export const managedFunctionRouteRegistry = new ManagedFunctionRouteRegistry();
